632	        modeIndicator: document.getElementById('mode-indicator'),
633	        cycleBtn: document.getElementById('cycle-btn'),
634	        resetBtn: document.getElementById('reset-btn'),
635	        helpBtn: document.getElementById('help-btn'),
636	        helpModal: document.getElementById('help-modal'),
637	        modalClose: document.getElementById('modal-close')
638	      };
