671	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
672	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
673	
674	      const storage = {
675	        save() {
676	          clearTimeout(saveTimeout);
677	          saveTimeout = setTimeout(() => {
